 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            colors = {grid[rr][cc] for rr, cc in cells}
            if len(colors) == 3:
                r0, r1 = min(rr for rr, _ in cells), max(rr for rr, _ in cells)
                c0, c1 = min(cc for _, cc in cells), max(cc for _, cc in cells)
                candidates.append([row[c0:c1+1] for row in grid[r0:r1+1]])
    if len(candidates) != 1:
        raise ValueError(f"expected one 3-color component, got {len(candidates)}")
    return candidates[0]
